{
  "hypothesis": "Convert the Revenue column to numeric type by parsing values with currency symbols, commas, and abbreviations like 'k'. Preserve existing missing values.",
  "columns": ["Revenue"],
  "operation": "clean_numeric_string",
  "parameters": {
    "mapping": {
      "$<digits>,<digits>.<digits>": "float",
      "$<digits>.<digits>": "float",
      "<digits>.<digits><letters>": "float",
      "<digits><letters>": "float",
      "<letters>": "ignore",
      "<letters>_<digits>": "ignore"
    },
    "errors": "coerce",
    "strategy": "fill_constant",
    "fill_value": "NaN"
  },
  "checks": [
    {
      "column": "Revenue",
      "kind": "numeric"
    },
    {
      "column": "Revenue",
      "kind": "non_negative"
    },
    {
      "column": "Revenue",
      "kind": "preserve_missing"
    }
  ],
  "value_assessment": {
    "evidence": "The Revenue column contains values with currency symbols, commas, and abbreviations like 'k'.",
    "interpretation": "These values represent monetary amounts and can be parsed into numeric format.",
    "preservation": "Existing missing values will be preserved during the conversion.",
    "ambiguities": "Values like 'banana' or 'ERROR_404' may not be parseable and could become NaN."
  }
}

